diff --git a/src/utils/webmcp.ts b/src/utils/webmcp.ts
new file mode 100644
index 0000000..bfd54e6
--- /dev/null
+++ b/src/utils/webmcp.ts
@@ -0,0 +1,112 @@
+import { useEffect, useRef } from 'react';
+
+/**
+ * Minimal helpers for exposing client-side functionality to AI agents via
+ * WebMCP (`navigator.modelContext`). When the browser (or an extension/polyfill)
+ * doesn't provide the API, everything here is a no-op.
+ */
+
+export interface JSONSchema {
+  type?: string | string[];
+  description?: string;
+  properties?: Record<string, JSONSchema>;
+  required?: string[];
+  minLength?: number;
+  maxLength?: number;
+  pattern?: string;
+  additionalProperties?: boolean;
+  [key: string]: unknown;
+}
+
+export interface ToolContent {
+  type: 'text';
+  text: string;
+}
+
+export interface ToolResult {
+  content: ToolContent[];
+  isError?: boolean;
+}
+
+export interface ModelContextTool<Input = Record<string, unknown>> {
+  name: string;
+  description: string;
+  inputSchema: JSONSchema;
+  annotations?: { readOnlyHint?: boolean; [key: string]: unknown };
+  execute: (input: Input, client?: unknown) => Promise<ToolResult> | ToolResult;
+}
+
+export interface ModelContext {
+  registerTool: (
+    tool: ModelContextTool<any>,
+    options?: { signal?: AbortSignal },
+  ) => unknown;
+  unregisterTool?: (name: string) => void;
+}
+
+declare global {
+  interface Navigator {
+    modelContext?: ModelContext;
+  }
+}
+
+/** Build a text result for a tool call. */
+export function textResult(data: unknown, isError = false): ToolResult {
+  return {
+    content: [{ type: 'text', text: typeof data === 'string' ? data : JSON.stringify(data) }],
+    ...(isError ? { isError: true } : {}),
+  };
+}
+
+/**
+ * Register a WebMCP tool for the lifetime of the calling component.
+ * The latest `execute` is always used, so it may freely close over state.
+ */
+export function useWebMCPTool<Input>(tool: ModelContextTool<Input>): void {
+  const executeRef = useRef(tool.execute);
+  executeRef.current = tool.execute;
+
+  const { name, description } = tool;
+  const schemaKey = JSON.stringify(tool.inputSchema);
+  const annotationsKey = JSON.stringify(tool.annotations ?? null);
+
+  useEffect(() => {
+    const modelContext = typeof navigator !== 'undefined' ? navigator.modelContext : undefined;
+    if (!modelContext?.registerTool) return;
+
+    const controller = new AbortController();
+    try {
+      modelContext.registerTool(
+        {
+          name,
+          description,
+          inputSchema: JSON.parse(schemaKey),
+          ...(annotationsKey !== 'null' ? { annotations: JSON.parse(annotationsKey) } : {}),
+          execute: async (input: Input, client?: unknown) => {
+            try {
+              return await executeRef.current((input ?? {}) as Input, client);
+            } catch (err) {
+              return textResult(
+                { success: false, error: err instanceof Error ? err.message : String(err) },
+                true,
+              );
+            }
+          },
+        },
+        { signal: controller.signal },
+      );
+    } catch (err) {
+      console.warn(`[webmcp] Failed to register tool "${name}":`, err);
+      return;
+    }
+
+    return () => {
+      controller.abort();
+      try {
+        modelContext.unregisterTool?.(name);
+      } catch {
+        // Already unregistered via the abort signal.
+      }
+    };
+  }, [name, description, schemaKey, annotationsKey]);
+}

