+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: body,
+        keepalive: true,
+        credentials: 'same-origin',
+        priority: urgent ? 'auto' : 'low'
+      }).catch(function () { /* analytics must never break the page */ });
+    }
+  }
