+++ b/js/delivery-crypto.js
@@ -0,0 +1,219 @@
+// Daily Grind — sealed delivery notes.
+//
+// Hybrid public-key encryption for customer delivery notes:
+//
+//   KEM   : X-Wing (ML-KEM-768 + X25519), draft-connolly-cfrg-xwing-kem.
+//           The shared secret stays safe as long as EITHER ML-KEM-768
+//           (post-quantum) OR X25519 (classical) is unbroken.
+//   KDF   : HKDF-SHA-256 (WebCrypto), bound to the suite, key id,
+//           KEM ciphertext and the authenticated header.
+//   AEAD  : AES-256-GCM (WebCrypto), 96-bit random nonce, header as AAD.
+//
+// Works unchanged in modern browsers and Node.js >= 20 (global WebCrypto).
+// Only ciphertext ever leaves the device; the plaintext note is never sent.
+
+import { xwing } from '../vendor/noble-xwing.min.js';
+
+export const SUITE = 'DG-SEALED-NOTE-v1/XWING-MLKEM768-X25519/HKDF-SHA256/AES-256-GCM';
+export const PUBLIC_KEY_BYTES = 1216; // X-Wing encapsulation key
+export const SECRET_KEY_BYTES = 32;   // X-Wing decapsulation key (seed form)
+export const KEM_CT_BYTES = 1120;     // X-Wing ciphertext
+export const MAX_NOTE_CHARS = 1000;
+
+const subtle = globalThis.crypto?.subtle;
+const enc = new TextEncoder();
+const dec = new TextDecoder('utf-8', { fatal: true });
+
+function requireCrypto() {
+  if (!subtle || !globalThis.crypto.getRandomValues) {
+    throw new Error('Secure WebCrypto is unavailable (a secure HTTPS context is required).');
+  }
+}
+
+// ---------- encoding helpers ----------
+
+export function toB64u(bytes) {
+  let bin = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromB64u(str, expectedLen) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new Error('Invalid base64url field.');
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  if (expectedLen !== undefined && out.length !== expectedLen) {
+    throw new Error(`Unexpected field length ${out.length} (expected ${expectedLen}).`);
+  }
+  return out;
+}
+
+function concat(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let off = 0;
+  for (const p of parts) { out.set(p, off); off += p.length; }
+  return out;
+}
+
+function lenPrefixed(bytes) {
+  const len = new Uint8Array(4);
+  new DataView(len.buffer).setUint32(0, bytes.length);
+  return concat(len, bytes);
+}
+
+// ---------- key ids / fingerprints ----------
+
+/** Key id = first 16 bytes of SHA-256(suite || publicKey), hex. */
+export async function keyId(publicKey) {
+  requireCrypto();
+  const h = new Uint8Array(await subtle.digest('SHA-256', concat(enc.encode(SUITE), publicKey)));
+  return Array.from(h.subarray(0, 16), (b) => b.toString(16).padStart(2, '0')).join('');
+}
+
+export function formatFingerprint(kid) {
+  return kid.match(/.{1,4}/g).join(' ').toUpperCase();
+}
+
+// ---------- recipient key handling ----------
+
+/** Validate a published recipient key document and return its raw bytes. */
+export async function parsePublicKeyDoc(doc) {
+  if (!doc || doc.suite !== SUITE) throw new Error('Delivery key uses an unsupported suite.');
+  const publicKey = fromB64u(doc.publicKey, PUBLIC_KEY_BYTES);
+  const kid = await keyId(publicKey);
+  if (doc.kid !== kid) throw new Error('Delivery key id does not match key material.');
+  return { kid, publicKey };
+}
+
+/** Generate a new recipient (dispatch) key pair. Staff-side only. */
+export async function generateRecipientKeys() {
+  requireCrypto();
+  const seed = globalThis.crypto.getRandomValues(new Uint8Array(SECRET_KEY_BYTES));
+  const { publicKey, secretKey } = xwing.keygen(seed);
+  seed.fill(0);
+  const kid = await keyId(publicKey);
+  return {
+    publicDoc: { suite: SUITE, kid, publicKey: toB64u(publicKey) },
+    privateDoc: { suite: SUITE, kid, secretKey: toB64u(secretKey) },
+  };
+}
+
+// ---------- key schedule ----------
+
+function canonicalHeader(h) {
+  // Fixed field order => deterministic bytes for AAD and KDF binding.
+  return enc.encode(JSON.stringify([h.v, h.suite, h.kid, h.orderRef, h.createdAt]));
+}
+
+async function deriveAeadKey(sharedSecret, kemCt, headerBytes) {
+  const ikm = await subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  // WebCrypto caps HKDF info at 1024 bytes, so bind a hash of the transcript
+  // (suite || header || KEM ciphertext) rather than the 1120-byte ciphertext itself.
+  const transcript = concat(
+    lenPrefixed(enc.encode(SUITE)),
+    lenPrefixed(headerBytes),
+    lenPrefixed(kemCt),
+  );
+  const info = concat(
+    enc.encode('DailyGrind/sealed-note/key/v1'),
+    new Uint8Array(await subtle.digest('SHA-256', transcript)),
+  );
+  return subtle.deriveKey(
+    { name: 'HKDF', hash: 'SHA-256', salt: enc.encode('DailyGrind/sealed-note/salt/v1'), info },
+    ikm,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    ['encrypt', 'decrypt'],
+  );
+}
+
+function validateOrderRef(orderRef) {
+  const ref = String(orderRef ?? '').trim();
+  if (ref.length > 64 || !/^[A-Za-z0-9#_-]*$/.test(ref)) {
+    throw new Error('Order reference may only contain letters, numbers, #, - and _ (max 64).');
+  }
+  return ref;
+}
+
+// ---------- seal / open ----------
+
+/**
+ * Encrypt a note to the dispatch team's public key.
+ * @returns a JSON-serialisable envelope containing only public data + ciphertext.
+ */
+export async function sealNote(note, recipient, { orderRef = '' } = {}) {
+  requireCrypto();
+  if (typeof note !== 'string' || note.trim() === '') throw new Error('Note is empty.');
+  if (note.length > MAX_NOTE_CHARS) throw new Error(`Note exceeds ${MAX_NOTE_CHARS} characters.`);
+
+  const header = {
+    v: 1,
+    suite: SUITE,
+    kid: recipient.kid,
+    orderRef: validateOrderRef(orderRef),
+    createdAt: new Date().toISOString(),
+  };
+  const headerBytes = canonicalHeader(header);
+
+  // Fresh encapsulation per note => fresh shared secret per note.
+  const { cipherText: kemCt, sharedSecret } = xwing.encapsulate(recipient.publicKey);
+  let key;
+  try {
+    key = await deriveAeadKey(sharedSecret, kemCt, headerBytes);
+  } finally {
+    sharedSecret.fill(0);
+  }
+
+  const iv = globalThis.crypto.getRandomValues(new Uint8Array(12));
+  const pt = enc.encode(note);
+  const ct = new Uint8Array(
+    await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: headerBytes, tagLength: 128 }, key, pt),
+  );
+  pt.fill(0);
+
+  return { ...header, kem: toB64u(kemCt), iv: toB64u(iv), ct: toB64u(ct) };
+}
+
+/** Decrypt an envelope with the dispatch secret key. Staff-side only. */
+export async function openNote(envelope, secretKeyB64u) {
+  requireCrypto();
+  if (!envelope || envelope.v !== 1 || envelope.suite !== SUITE) {
+    throw new Error('Unsupported envelope version or suite.');
+  }
+  const secretKey = fromB64u(secretKeyB64u, SECRET_KEY_BYTES);
+  const header = {
+    v: envelope.v,
+    suite: envelope.suite,
+    kid: String(envelope.kid),
+    orderRef: validateOrderRef(envelope.orderRef),
+    createdAt: String(envelope.createdAt),
+  };
+  const headerBytes = canonicalHeader(header);
+  const kemCt = fromB64u(envelope.kem, KEM_CT_BYTES);
+  const iv = fromB64u(envelope.iv, 12);
+  const ct = fromB64u(envelope.ct);
+  if (ct.length < 16) throw new Error('Ciphertext too short.');
+
+  const sharedSecret = xwing.decapsulate(kemCt, secretKey);
+  secretKey.fill(0);
+  let key;
+  try {
+    key = await deriveAeadKey(sharedSecret, kemCt, headerBytes);
+  } finally {
+    sharedSecret.fill(0);
+  }
+
+  let pt;
+  try {
+    pt = await subtle.decrypt({ name: 'AES-GCM', iv, additionalData: headerBytes, tagLength: 128 }, key, ct);
+  } catch {
+    throw new Error('Authentication failed: wrong key or the note was tampered with.');
+  }
+  return { header, note: dec.decode(pt) };
+}
