@@ -0,0 +1,91 @@
+// UI wiring for the sealed delivery notes form on the homepage.
+import {
+  parsePublicKeyDoc, sealNote, toB64u, formatFingerprint, MAX_NOTE_CHARS,
+} from './delivery-crypto.js';
+
+const $ = (id) => document.getElementById(id);
+const form = $('sealed-note-form');
+const noteEl = $('sealed-note-text');
+const refEl = $('sealed-note-ref');
+const counter = $('sealed-note-count');
+const statusEl = $('sealed-note-status');
+const fpEl = $('sealed-note-fingerprint');
+const sealBtn = $('sealed-note-seal');
+const result = $('sealed-note-result');
+const tokenEl = $('sealed-note-token');
+const copyBtn = $('sealed-note-copy');
+const attachForm = $('sealed-note-attach');
+const hiddenEnvelope = $('sealed-note-envelope');
+const hiddenRef = $('sealed-note-order-ref');
+
+let recipient = null;
+
+function setStatus(msg, kind = 'info') {
+  statusEl.textContent = msg;
+  statusEl.dataset.kind = kind;
+}
+
+function updateCounter() {
+  counter.textContent = `${noteEl.value.length} / ${MAX_NOTE_CHARS}`;
+}
+
+async function loadRecipientKey() {
+  try {
+    if (!window.isSecureContext || !crypto?.subtle) {
+      throw new Error('Encryption needs a secure (HTTPS) connection.');
+    }
+    const res = await fetch('keys/delivery-public.json', { cache: 'no-cache', credentials: 'omit' });
+    if (!res.ok) throw new Error(`Could not load the delivery key (HTTP ${res.status}).`);
+    recipient = await parsePublicKeyDoc(await res.json());
+    fpEl.textContent = formatFingerprint(recipient.kid);
+    sealBtn.disabled = false;
+    setStatus('Ready — your note is encrypted on this device before anything is sent.', 'ok');
+  } catch (err) {
+    sealBtn.disabled = true;
+    setStatus(`Sealed notes unavailable: ${err.message}`, 'error');
+  }
+}
+
+form.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  if (!recipient) return;
+  sealBtn.disabled = true;
+  setStatus('Encrypting…');
+  try {
+    const envelope = await sealNote(noteEl.value, recipient, { orderRef: refEl.value });
+    const json = JSON.stringify(envelope);
+    const token = 'DGNOTE1.' + toB64u(new TextEncoder().encode(json));
+    tokenEl.value = token;
+    hiddenEnvelope.value = json;
+    hiddenRef.value = envelope.orderRef;
+    result.hidden = false;
+    // Drop the plaintext from the page as soon as it is sealed.
+    noteEl.value = '';
+    updateCounter();
+    setStatus('Sealed. Only our dispatch team’s private key can open this note.', 'ok');
+  } catch (err) {
+    setStatus(`Could not seal note: ${err.message}`, 'error');
+  } finally {
+    sealBtn.disabled = false;
+  }
+});
+
+copyBtn.addEventListener('click', async () => {
+  try {
+    await navigator.clipboard.writeText(tokenEl.value);
+    copyBtn.textContent = 'Copied!';
+  } catch {
+    tokenEl.select();
+    copyBtn.textContent = 'Press Ctrl+C';
+  }
+  setTimeout(() => { copyBtn.textContent = 'Copy'; }, 2000);
+});
+
+attachForm.addEventListener('submit', (e) => {
+  if (!hiddenEnvelope.value) e.preventDefault();
+});
+
+noteEl.maxLength = MAX_NOTE_CHARS;
+noteEl.addEventListener('input', updateCounter);
+updateCounter();
+loadRecipientKey();
