new file mode 100644
index 0000000..66d0dcb
--- /dev/null
+++ b/scripts/generate-delivery-keys.mjs
@@ -0,0 +1,27 @@
+#!/usr/bin/env node
+// Generate the dispatch team's X-Wing (ML-KEM-768 + X25519) key pair.
+//   node scripts/generate-delivery-keys.mjs [--force]
+// Writes the PUBLIC key to keys/delivery-public.json (served to browsers)
+// and the SECRET key to keys/private/delivery-secret.json (git-ignored, mode 0600).
+import { mkdir, writeFile, access } from 'node:fs/promises';
+import { dirname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { generateRecipientKeys, formatFingerprint } from '../js/delivery-crypto.js';
+
+const root = join(dirname(fileURLToPath(import.meta.url)), '..');
+const pubPath = join(root, 'keys', 'delivery-public.json');
+const secPath = join(root, 'keys', 'private', 'delivery-secret.json');
+
+const exists = await access(secPath).then(() => true, () => false);
+if (exists && !process.argv.includes('--force')) {
+  console.error(`Refusing to overwrite ${secPath} (pass --force to rotate keys; old notes become unreadable without the old key).`);
+  process.exit(1);
+}
+
+const { publicDoc, privateDoc } = await generateRecipientKeys();
+await mkdir(dirname(secPath), { recursive: true, mode: 0o700 });
+await writeFile(secPath, JSON.stringify(privateDoc, null, 2) + '\n', { mode: 0o600 });
+await writeFile(pubPath, JSON.stringify(publicDoc, null, 2) + '\n');
+console.log(`Key id / fingerprint: ${formatFingerprint(publicDoc.kid)}`);
+console.log(`Public key : ${pubPath}`);
+console.log(`Secret key : ${secPath}  (keep offline / in a secrets manager — never commit)`);
diff --git a/scripts/open-delivery-note.mjs b/scripts/open-delivery-note.mjs
new file mode 100644
index 0000000..da7dc08
--- /dev/null
+++ b/scripts/open-delivery-note.mjs
@@ -0,0 +1,43 @@
+#!/usr/bin/env node
+// Decrypt a sealed delivery note (staff only).
+//   node scripts/open-delivery-note.mjs <envelope.json | -> [--key keys/private/delivery-secret.json]
+// The envelope may be raw JSON or the base64url "DGNOTE1." token shown to customers.
+import { readFile } from 'node:fs/promises';
+import { dirname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { openNote, fromB64u } from '../js/delivery-crypto.js';
+
+const args = process.argv.slice(2);
+const keyIdx = args.indexOf('--key');
+const root = join(dirname(fileURLToPath(import.meta.url)), '..');
+const keyPath = keyIdx >= 0 ? args.splice(keyIdx, 2)[1] : join(root, 'keys', 'private', 'delivery-secret.json');
+const src = args[0];
+if (!src) {
+  console.error('Usage: open-delivery-note.mjs <envelope-file | -> [--key path]');
+  process.exit(2);
+}
+
+async function readStdin() {
+  const chunks = [];
+  for await (const c of process.stdin) chunks.push(c);
+  return Buffer.concat(chunks).toString('utf8');
+}
+
+try {
+  const raw = (src === '-' ? await readStdin() : await readFile(src, 'utf8')).trim();
+  const envelope = raw.startsWith('DGNOTE1.')
+    ? JSON.parse(new TextDecoder().decode(fromB64u(raw.slice(8))))
+    : JSON.parse(raw);
+  const priv = JSON.parse(await readFile(keyPath, 'utf8'));
+  if (priv.kid !== envelope.kid) {
+    throw new Error(`Note was sealed to key ${envelope.kid}, but loaded key is ${priv.kid}.`);
+  }
+  const { header, note } = await openNote(envelope, priv.secretKey);
+  console.log(`Order ref : ${header.orderRef || '(none)'}`);
+  console.log(`Sealed at : ${header.createdAt}`);
+  console.log('Note      :');
+  console.log(note);
+} catch (err) {
+  console.error(`Could not open note: ${err.message}`);
+  process.exit(1);
+}
