@@ -0,0 +1,15 @@
+// Non-critical: wires up the header theme toggle after parsing.
+// The visible label is driven by CSS from [data-theme], so it is correct on first paint.
+const button = document.querySelector('.theme-toggle');
+if (button) {
+  const root = document.documentElement;
+  const sync = () => button.setAttribute('aria-pressed', String(root.dataset.theme === 'dark'));
+  sync();
+  button.addEventListener('click', () => {
+    root.dataset.theme = root.dataset.theme === 'dark' ? 'light' : 'dark';
+    try {
+      localStorage.setItem('theme', root.dataset.theme);
+    } catch {}
+    sync();
+  });
+}
