+  <script>
+    // Copy buttons: each button names its source element via commandfor (Invoker Commands).
+    const timers = new WeakMap();
+    let lastMessage = '';
+
+    function report(button, ok) {
+      const tip = button.nextElementSibling; // the role="status" bubble
+      clearTimeout(timers.get(button));
+      button.removeAttribute('data-copied');
+      button.removeAttribute('data-failed');
+      let message = ok ? 'Copied' : 'Copy failed';
+      // VoiceOver skips a message identical to the previous one; a no-break space makes it differ
+      if (message === lastMessage) message += '\u00A0';
+      lastMessage = message;
+      tip.textContent = '';
+      void button.offsetWidth; // restart the CSS animation
+      button.setAttribute(ok ? 'data-copied' : 'data-failed', '');
+      requestAnimationFrame(() => (tip.textContent = message));
+      timers.set(button, setTimeout(() => {
+        button.removeAttribute('data-copied');
+        button.removeAttribute('data-failed');
+        tip.textContent = '';
+      }, 2000));
+    }
+
+    async function copy(button, target) {
+      const text = target.matches('input, textarea') ? target.value : target.innerText.trim();
+      if (!text) return;
+      try {
+        await navigator.clipboard.writeText(text);
+        report(button, true);
+      } catch {
+        report(button, false);
+      }
+    }
+
+    if ('CommandEvent' in window) {
+      // command events don't bubble: listen in the capture phase
+      document.addEventListener('command', (event) => {
+        if (event.command === '--copy') copy(event.source, event.target);
+      }, true);
+    } else {
+      document.addEventListener('click', (event) => {
+        const button = event.target.closest('button[command="--copy"]');
+        if (!button) return;
+        const target = document.getElementById(button.getAttribute('commandfor'));
+        if (target) copy(button, target);
+      });
+    }
+  </script>
 </body>

