+// smallpt, a Path Tracer by Kevin Beason, 2008
+// Original: http://www.kevinbeason.com/smallpt/ (MIT-style license)
+//
+// WebAssembly port: the scene, intersection and radiance() code are unchanged
+// from the original. main() is replaced by a small C API so the browser can
+// render progressively (one pass of 2x2 subpixel samples at a time), read the
+// RGBA framebuffer straight out of linear memory, and recolor the spheres.
+#include <math.h>
+#include <stdlib.h>
+#include <emscripten/emscripten.h>
+
+struct Vec {
+  double x, y, z;                  // position, also color (r,g,b)
+  Vec(double x_=0, double y_=0, double z_=0){ x=x_; y=y_; z=z_; }
+  Vec operator+(const Vec &b) const { return Vec(x+b.x,y+b.y,z+b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x-b.x,y-b.y,z-b.z); }
+  Vec operator*(double b) const { return Vec(x*b,y*b,z*b); }
+  Vec mult(const Vec &b) const { return Vec(x*b.x,y*b.y,z*b.z); }
+  Vec& norm(){ return *this = *this * (1/sqrt(x*x+y*y+z*z)); }
+  double dot(const Vec &b) const { return x*b.x+y*b.y+z*b.z; } // cross:
+  Vec operator%(const Vec&b) const {return Vec(y*b.z-z*b.y,z*b.x-x*b.z,x*b.y-y*b.x);}
+};
