+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+// ---------------------------------------------------------------------------
+// Browser API
+// ---------------------------------------------------------------------------
+static int W = 0, H = 0, passes = 0;
+static Vec *accum = nullptr;            // running sum of per-pass pixel colors
+static unsigned char *rgba = nullptr;   // display buffer (RGBA8, top row first)
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE int sphere_count() { return NUM_SPHERES; }
+
+EMSCRIPTEN_KEEPALIVE void set_sphere_color(int i, double r, double g, double b) {
+  if (i >= 0 && i < NUM_SPHERES) spheres[i].c = Vec(r, g, b);
+}
+
+// Allocate buffers for a w*h image and clear accumulated samples.
+EMSCRIPTEN_KEEPALIVE unsigned char *init(int w, int h) {
+  free(accum); free(rgba);
+  W = w; H = h; passes = 0;
+  accum = (Vec *)calloc((size_t)w * h, sizeof(Vec));
+  rgba = (unsigned char *)malloc((size_t)w * h * 4);
+  return rgba;
+}
+
+// Render rows [y0, y1) for one pass: one sample in each of the 2x2 subpixels
+// (4 spp), using the original smallpt tent filter and camera.
+EMSCRIPTEN_KEEPALIVE void render_rows(int y0, int y1) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(W*.5135/H), cy=(cx%cam.d).norm()*.5135;
