+                  cy*( ( (sy+.5 + dy)/2 + y)/H - .5) + cam.d;
+          Vec r = radiance(Ray(cam.o+d*140,d.norm()),0,Xi);
+          c = c + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+        }
+      int i=(H-y-1)*W+x;
+      accum[i] = accum[i] + c;
+    }
+  }
+}
+
+// Mark a pass complete and refresh the RGBA buffer. Returns total spp.
+EMSCRIPTEN_KEEPALIVE int finish_pass() {
+  passes++;
+  double inv = 1.0 / passes;
+  for (int i=0; i<W*H; i++) {
+    Vec c = accum[i] * inv;
+    rgba[i*4+0] = toInt(c.x);
+    rgba[i*4+1] = toInt(c.y);
+    rgba[i*4+2] = toInt(c.z);
+    rgba[i*4+3] = 255;
+  }
+  return passes * 4;
+}
+
+}

