+
+// Set the diffuse/specular/refractive color of sphere `id` (components 0..1).
+EMSCRIPTEN_KEEPALIVE void set_sphere_color(int id, double r, double g, double b){
+  if (!defaultsSaved){
+    for (int i=0;i<NUM_SPHERES;i++) defaultColors[i]=spheres[i].c;
+    defaultsSaved = true;
+  }
+  if (id<0 || id>=NUM_SPHERES) return;
+  spheres[id].c = Vec(clamp(r),clamp(g),clamp(b));
+}
+
+// Restore the original Cornell-box colors.
+EMSCRIPTEN_KEEPALIVE void reset_sphere_colors(){
+  if (!defaultsSaved) return;
+  for (int i=0;i<NUM_SPHERES;i++) spheres[i].c = defaultColors[i];
+}
+
+// Progressive rendering. Each call traces one pass of a w*h image: one sample
+// per 2x2 subpixel (4 spp), using the same per-pixel logic as the original
+// main(). Radiance is accumulated across passes and the running average is
+// written to `out` as RGBA8 (w*h*4 bytes, top-down like the original PPM).
+// pass == 0 clears the accumulator (start a new image).
+static Vec *accum = 0;
+static int accSize = 0;
+
+EMSCRIPTEN_KEEPALIVE void render_pass(uint8_t *out, int w, int h, int pass){
+  if (w*h != accSize){ delete[] accum; accum = new Vec[w*h]; accSize = w*h; pass = 0; }
+  if (pass == 0) for (int i=0; i<w*h; i++) accum[i] = Vec();
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+  double inv = 1./(pass+1);
+  for (int y=0; y<h; y++){                       // Loop over image rows
+    for (unsigned short x=0, Xi[3]={(unsigned short)pass,(unsigned short)(pass*7919),(unsigned short)(y*y*y)}; x<w; x++){ // Loop cols
+      int i=(h-y-1)*w+x;
+      for (int sy=0; sy<2; sy++)                    // 2x2 subpixel rows
+        for (int sx=0; sx<2; sx++){                 // 2x2 subpixel cols
+          double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+          Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                  cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+          r = radiance(Ray(cam.o+d*140,d.norm()),0,Xi);
+          // Camera rays are pushed ^^^^^ forward to start in interior
+          accum[i] = accum[i] + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+        }
+      Vec c = accum[i]*inv;
+      uint8_t *px = out + i*4;
+      px[0]=toInt(c.x); px[1]=toInt(c.y); px[2]=toInt(c.z); px[3]=255;
+    }
+  }
+}
+
+} // extern "C"
