+// Web Worker that runs the smallpt WebAssembly module off the main thread and
+// streams progressively refined frames back to the page.
+import initSmallpt from './generated/smallpt.js';
+
+const modulePromise = initSmallpt();
+let currentJob = 0;
+
+self.onmessage = async ({ data }) => {
+  if (data.type !== 'render') return;
+  const job = ++currentJob;
+  try {
+    await render(job, data);
+  } catch (err) {
+    self.postMessage({ type: 'error', job: data.job, message: String(err) });
+  }
+};
+
+/**
+ * @param {number} job
+ * @param {{ job: number, width: number, height: number, passes: number,
+ *           colors: Array<[number, number, number, number]> }} opts
+ */
+async function render(job, { job: clientJob, width, height, passes, colors }) {
+  const wasm = await modulePromise;
+  wasm._reset_sphere_colors();
+  for (const [id, r, g, b] of colors) wasm._set_sphere_color(id, r, g, b);
+
+  const byteLength = width * height * 4;
+  const ptr = wasm._malloc(byteLength);
