+  // ---- FLIP animation ------------------------------------------------------
+  function snapshot() {
+    return {
+      x: scrollX,
+      y: scrollY,
+      rects: new Map(cards().map((c) => [c, c.getBoundingClientRect()])),
+    };
+  }
