+  <style>
+    :host {
+      --star-size: 2rem;
+      --star-gap: 0.25rem;
+      --star-fill: #ffab40;
+      --star-hover-fill: #ffc77a;
+      --star-empty: #d7ccc8;
+      --star-stroke: #8d6e63;
+      --star-focus: #4e342e;
+      display: inline-block;
+      vertical-align: middle;
+      -webkit-tap-highlight-color: transparent;
+    }
+    :host([hidden]) { display: none; }
+    :host(:disabled) { opacity: 0.45; }
+
+    .stars {
+      display: inline-flex;
+      gap: var(--star-gap);
+    }
+    .star {
+      display: inline-flex;
+      width: var(--star-size);
+      height: var(--star-size);
+      border-radius: 6px;
+      cursor: pointer;
+      outline: none;
+      transition: transform 0.12s ease;
+    }
+    :host(:disabled) .star { cursor: not-allowed; }
+    :host(:not(:disabled)) .star:hover { transform: scale(1.12); }
+    .star:focus-visible {
+      box-shadow: 0 0 0 2px #fff, 0 0 0 4px var(--star-focus);
+    }
+    svg {
+      width: 100%;
+      height: 100%;
+      pointer-events: none;
+    }
+    path {
+      fill: var(--star-empty);
+      stroke: var(--star-stroke);
+      stroke-width: 1;
+      stroke-linejoin: round;
+      transition: fill 0.12s ease;
+    }
+    .star.filled path { fill: var(--star-fill); }
