+    function updateLayout() {
+      const width = inner.clientWidth;
+      const wasWide = header.classList.contains("is-wide");
+      // While collapsed, only re-measure when the header has grown, to avoid layout thrash.
+      if (!wasWide && width <= lastWidth) {
+        lastWidth = width;
+        return;
+      }
+      lastWidth = width;
+
+      const wasOpen = !wasWide && isOpen();
+      if (wasOpen) menu.hidePopover();
+
+      header.classList.add("is-measuring", "is-wide");
+      const wide = inner.scrollWidth <= inner.clientWidth;
+
+      if (wide) {
+        menu.removeAttribute("popover");
+      } else {
+        header.classList.remove("is-wide");
