index 0000000..9d62af9
--- /dev/null
+++ b/src/components/ArticleImage.astro
@@ -0,0 +1,72 @@
+---
+/**
+ * Responsive article image.
+ *
+ * - Local (imported) images are optimized by Astro and get a `srcset` with
+ *   several widths plus a `sizes` hint so the browser downloads the smallest
+ *   adequate candidate.
+ * - Remote URLs (not optimizable here) render as a plain <img> with intrinsic
+ *   dimensions to avoid layout shift.
+ * - `priority` marks the image as the likely LCP element: it is loaded eagerly
+ *   with a high fetch priority instead of being lazy-loaded.
+ */
+import { Image } from 'astro:assets';
+import type { HTMLAttributes } from 'astro/types';
+
+export interface Props extends Omit<HTMLAttributes<'img'>, 'src' | 'width' | 'height' | 'alt'> {
+    src: ImageMetadata | string;
+    alt: string;
+    width: number;
+    height: number;
+    /** Candidate widths for the srcset (local images only). */
+    widths?: number[];
+    /** The `sizes` attribute describing the rendered slot width. */
+    sizes: string;
+    quality?: number;
+    priority?: boolean;
+}
+
+const {
+    src,
+    alt,
+    width,
+    height,
+    widths,
+    sizes,
+    quality,
+    priority = false,
+    ...attrs
+} = Astro.props;
+
+const loadingAttrs = priority
+    ? { loading: 'eager' as const, fetchpriority: 'high' as const, decoding: 'async' as const }
+    : { loading: 'lazy' as const, decoding: 'async' as const };
+
+// Default candidates: 0.5x, 1x and 2x of the nominal width, capped at 2400px.
+const candidateWidths = (widths ?? [Math.round(width / 2), width, width * 2])
+    .map((w) => Math.min(w, 2400))
+    .filter((w, i, arr) => w > 0 && arr.indexOf(w) === i)
+    .sort((a, b) => a - b);
+
+// Never upscale beyond the source image.
+const fitWidths = (sourceWidth: number) => {
+    const fitting = candidateWidths.filter((w) => w <= sourceWidth);
+    return fitting.length > 0 ? fitting : [sourceWidth];
+};
+---
+{typeof src === 'string' ? (
+    <img src={src} alt={alt} width={width} height={height} {...loadingAttrs} {...attrs} />
+) : (
+    <Image
+        src={src}
+        alt={alt}
+        width={width}
+        height={height}
+        widths={fitWidths(src.width)}
+        sizes={sizes}
+        format="webp"
+        quality={quality}
+        {...loadingAttrs}
+        {...attrs}
+    />
+)}
