diff --git a/src/components/ModalDialog.tsx b/src/components/ModalDialog.tsx
new file mode 100644
index 0000000..7749520
--- /dev/null
+++ b/src/components/ModalDialog.tsx
@@ -0,0 +1,83 @@
+import { useEffect, useRef, type ReactNode, type RefObject } from 'react';
+
+interface Props {
+  open: boolean;
+  onClose: () => void;
+  /** id of the element that labels the dialog (usually its heading). */
+  labelledBy: string;
+  /** Element to focus once the dialog opens. Defaults to the browser's dialog focusing steps. */
+  initialFocusRef?: RefObject<HTMLElement | null>;
+  className?: string;
+  children: ReactNode;
+}
+
+/**
+ * Thin wrapper around the native <dialog> element opened with showModal().
+ * The browser provides the top layer, ::backdrop, inertness of the rest of the
+ * page, focus containment, Escape-to-close and focus restoration to the invoker.
+ */
+export default function ModalDialog({ open, onClose, labelledBy, initialFocusRef, className = '', children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const pointerDownOnBackdrop = useRef(false);
+  const onCloseRef = useRef(onClose);
+  onCloseRef.current = onClose;
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (open && !dialog.open) {
+      dialog.showModal();
+      initialFocusRef?.current?.focus();
+    } else if (!open && dialog.open) {
+      dialog.close();
+    }
+  }, [open, initialFocusRef]);
+
+  // Fires for Escape, close buttons, light dismiss and programmatic close().
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    const handleClose = () => onCloseRef.current();
+    dialog.addEventListener('close', handleClose);
+    return () => dialog.removeEventListener('close', handleClose);
+  }, []);
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={labelledBy}
+      className={`modal-dialog ${className}`}
+      // Native light dismiss where supported; the click handler below is the fallback.
+      closedby="any"
+      onPointerDown={(e) => {
+        pointerDownOnBackdrop.current = e.target === e.currentTarget;
+      }}
+      onClick={(e) => {
+        // The dialog has no padding, so a click whose target is the <dialog>
+        // itself landed on the ::backdrop.
+        if (pointerDownOnBackdrop.current && e.target === e.currentTarget) {
+          e.currentTarget.close();
+        }
+        pointerDownOnBackdrop.current = false;
+      }}
+    >
+      {open && children}
+    </dialog>
+  );
+}
+
+export function CloseDialogButton({ label = 'Close' }: { label?: string }) {
+  return (
+    <form method="dialog" className="absolute top-2 right-2">
+      <button
+        type="submit"
+        aria-label={label}
+        className="rounded-full p-1 text-gray-500 hover:text-amber-500 hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-amber-500"
+      >
+        <svg aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+          <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+        </svg>
+      </button>
+    </form>
+  );
+}
