+}
+
+/* Section navigation flyout (native popover), anchored below the main nav bar. */
+.site-nav {
+  anchor-name: --site-nav;
+}
+
+.nav-flyout {
+  position: fixed;
+  inset: auto;
+  margin: 0;
+  padding: 0;
+  border: 0;
+  position-anchor: --site-nav;
+  top: anchor(bottom);
+  left: anchor(left);
+  width: anchor-size(width);
+}
+
+@supports not (anchor-name: --a) {
+  .nav-flyout {
+    /* --flyout-top is set from JS when anchor positioning is unavailable. */
+    top: var(--flyout-top, 0px);
+    left: 50%;
+    translate: -50% 0;
+    width: min(72rem, 100vw);
+  }
+}
+
+/* Native modal dialogs */
+.modal-dialog {
+  margin-inline: auto;
+  margin-block: 15vh auto;
+  padding: 0;
+  border: 0;
+  width: calc(100% - 2rem);
+  max-width: 42rem;
+  max-height: 75vh;
+  background: white;
+  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
+}
+
+.modal-dialog::backdrop {
+  background: rgb(255 255 255 / 0.3);
+  backdrop-filter: blur(4px);
+}
+
+@media (prefers-reduced-motion: no-preference) {
+  .modal-dialog[open] {
+    animation: dialog-in 150ms ease-out;
+  }
+}
+
+@keyframes dialog-in {
+  from {
+    opacity: 0;
+    translate: 0 -0.5rem;
+  }
+}
+
+/* Prevent the page behind an open modal dialog from scrolling. */
+html:has(dialog[open]:modal) {
+  overflow: hidden;
