+/* ==========================================================
+   Barista order-tracking board
+   ========================================================== */
+.board-section {
+  --drop-marker-color: var(--accent);
+  --drop-line-size: 3px;
+  --board-gap: 12px;
+  --lift-shadow: 0 12px 28px rgba(62, 39, 35, 0.28), 0 4px 8px rgba(62, 39, 35, 0.18);
+  margin-top: 60px;
+}
+
+.board-section > h2 {
+  text-align: center;
+}
+
+.board-intro {
+  text-align: center;
+  color: #6d4c41;
+  margin-bottom: 20px;
+}
+
+/* ---------- New order form ---------- */
+.order-form {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
+  gap: 10px 14px;
+  align-items: end;
+  background: white;
+  border-radius: 8px;
+  padding: 16px;
+  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+  margin-bottom: 24px;
+}
+
+.order-form label {
+  display: grid;
+  gap: 4px;
+  font-size: 0.8rem;
+  font-weight: 600;
+  color: var(--primary);
+}
+
+.order-form input,
+.order-form select {
+  width: 100%;
+  font: inherit;
+  font-size: 0.9rem;
+  padding: 7px 9px;
+  border: 1px solid var(--secondary);
+  border-radius: 5px;
+  background: var(--light);
+  color: var(--text);
+}
+
+.order-form input:focus-visible,
+.order-form select:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 1px;
+}
+
+.order-form button {
+  font: inherit;
+  font-weight: 600;
+  border: 0;
+  border-radius: 5px;
+  padding: 9px 14px;
+  background: var(--primary);
+  color: white;
+  cursor: pointer;
+}
+
+.order-form button:hover,
+.order-form button:focus-visible {
+  background: var(--text);
+}
+
+/* ---------- Board ---------- */
+.board {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 18px;
