+  align-items: center;
+  justify-content: space-between;
+  padding: 12px 14px 4px;
+}
+
+.column-header h3 {
+  font-size: 1rem;
+  color: var(--primary);
+  letter-spacing: 0.5px;
+  text-transform: uppercase;
+}
+
+.column-count {
+  min-width: 1.8em;
+  text-align: center;
+  font-size: 0.8rem;
+  font-weight: 700;
+  padding: 1px 8px;
+  border-radius: 999px;
+  background: var(--column-color);
+  color: white;
+}
+
+.board-column[data-status="brewing"] .column-count {
+  color: var(--text);
+}
+
+.card-list {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  gap: var(--board-gap);
+  list-style: none;
+  padding: 10px 12px 14px;
+  flex: 1;
