+  }
+}
+
+/* ---------- Order cards ---------- */
+.board .card {
+  position: relative;
+  text-align: start;
+  padding: 10px 12px 12px;
+  border-radius: 8px;
+  border-left: 4px solid var(--column-color, var(--primary));
+  scroll-margin: 16px;
+}
+
+.board .card:has(.card-handle:focus-visible) {
