+  outline: none;
+}
+
+html.is-dragging,
+html.is-dragging * {
+  cursor: grabbing !important;
+}
+
+.card-number {
+  font-weight: 700;
+  color: var(--primary);
+}
+
+.card-age {
+  margin-left: auto;
+  font-variant-numeric: tabular-nums;
+}
+
+.card-age.is-late {
+  color: #c62828;
