+  font-size: 0.85rem;
+}
+
+.card-meta {
+  color: #6d4c41;
+}
+
+.card-notes {
+  font-style: italic;
+  color: #795548;
+}
+
+.card-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px;
+  margin-top: 10px;
+}
+
+.card-actions button {
+  flex: 1 1 auto;
+  font: inherit;
+  font-size: 0.78rem;
+  font-weight: 600;
+  padding: 5px 8px;
