+  color: var(--primary);
+  cursor: pointer;
+}
+
+.card-actions button:is(:hover, :focus-visible) {
+  background: var(--secondary);
+}
+
+.card-actions button:focus-visible {
+  outline: 2px solid var(--primary);
+  outline-offset: 1px;
+}
+
+.card-actions .card-done {
+  background: #43a047;
+  border-color: #43a047;
+  color: white;
+}
+
+.card-actions .card-done:is(:hover, :focus-visible) {
+  background: #2e7d32;
+}
+
+.visually-hidden {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  overflow: hidden;
+  clip-path: inset(50%);
+  white-space: nowrap;
+}

