+type Status = 'idle' | 'connecting' | 'ok' | 'error';
+
+interface ProbeResult {
+  status: Status;
+  message?: string;
+  httpStatus?: number;
+  latencyMs?: number;
+  body?: string;
+  at?: string;
+}
