+          clientExtensionResults: cred.getClientExtensionResults(),
+          response,
+        };
+      }
+
+      // ---------- capability detection ----------
+      async function canSilentlyRegisterPasskey() {
+        if (!window.isSecureContext) return false;
+        if (typeof window.PublicKeyCredential === 'undefined') return false;
+        if (!navigator.credentials || typeof navigator.credentials.create !== 'function') return false;
+        if (typeof PublicKeyCredential.getClientCapabilities !== 'function') return false;
+        try {
+          const caps = await PublicKeyCredential.getClientCapabilities();
+          // conditionalCreate = browser can create a passkey without a modal
+          // right after a password sign-in through its password manager.
+          return caps.conditionalCreate === true;
+        } catch (_) {
+          return false;
+        }
+      }
+
+      // ---------- orphan cleanup ----------
+      async function signalOrphanedCredential(rpId, credentialId) {
+        if (!rpId || !credentialId) return;
+        if (typeof PublicKeyCredential.signalUnknownCredential !== 'function') return;
+        try {
+          await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId });
+        } catch (_) {
+          // best effort only
+        }
+      }
+
+      // ---------- silent passkey upgrade ----------
+      async function silentlyRegisterPasskey() {
+        if (!(await canSilentlyRegisterPasskey())) return;
+
+        const optionsRes = await fetch('/api/register/options', {
+          method: 'POST',
+          credentials: 'same-origin',
+          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+          body: JSON.stringify({}),
+        });
+        if (!optionsRes.ok) return;
+
+        const optionsJSON = await optionsRes.json();
+        const publicKey = parseCreationOptions(optionsJSON.publicKey || optionsJSON);
+        const rpId = (publicKey.rp && publicKey.rp.id) || location.hostname;
+
+        let credential;
+        try {
+          credential = await navigator.credentials.create({
+            publicKey,
+            mediation: 'conditional',
+          });
+        } catch (_) {
+          // NotAllowedError etc.: browser declined to create silently. Do nothing.
+          return;
+        }
+        if (!credential) return;
+
+        let verified = false;
+        try {
+          const verifyRes = await fetch('/api/register/verify', {
+            method: 'POST',
+            credentials: 'same-origin',
+            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+            body: JSON.stringify(credentialToJSON(credential)),
+          });
+          if (verifyRes.ok) {
+            const body = await verifyRes.json().catch(() => ({}));
+            verified = body.verified !== false;
+          }
+        } catch (_) {
+          verified = false;
+        }
+
+        if (!verified) {
+          // The authenticator saved a passkey the server doesn't know about;
+          // tell the credential manager to remove it.
+          await signalOrphanedCredential(rpId, credential.id);
+        }
+      }
+
+      // ---------- password sign-in ----------
+      form.addEventListener('submit', async (event) => {
+        event.preventDefault();
+
+        const username = form.username.value.trim();
+        const password = form.password.value;
+        if (!username || !password) {
+          showMessage('Please enter your username and password.', 'error');
+          return;
+        }
+
+        button.disabled = true;
+        showMessage('Signing in…');
+
+        let ok = false;
+        try {
+          const res = await fetch('/api/login', {
+            method: 'POST',
+            credentials: 'same-origin',
+            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+            body: JSON.stringify({ username, password }),
+          });
+          ok = res.ok;
+          if (!ok) {
+            const body = await res.json().catch(() => ({}));
+            showMessage(body.error || body.message || 'Invalid username or password.', 'error');
+          }
+        } catch (_) {
+          showMessage('Unable to reach the server. Please try again.', 'error');
+        } finally {
+          button.disabled = false;
+        }
+
+        if (!ok) return;
+
+        showMessage('Welcome back! You are signed in.', 'success');
+
+        // Fire-and-forget: never surfaces UI or errors to the user.
+        silentlyRegisterPasskey().catch((err) => {
+          console.debug('Silent passkey registration skipped:', err);
+        });
+      });
+    })();
+  </script>
+
 </body>

 </html>

