+        </label>
+        <label>
+          <span>Display name</span>
+          <input name="displayName" type="text" autocomplete="name" required maxlength="64">
+        </label>
+        <button type="submit" class="btn">Save profile</button>
+      </form>
+    </section>
+
+    <!-- Passkeys -->
+    <section class="panel" aria-labelledby="passkeys-title">
+      <div class="panel-header">
+        <div>
+          <h2 id="passkeys-title">Passkeys</h2>
+          <p class="muted">Sign in with your fingerprint, face, screen lock, or a security key — no password needed.</p>
+        </div>
+        <button type="button" id="create-passkey" class="btn" hidden>Create a passkey</button>
+      </div>
+
+      <p id="passkey-unsupported" class="muted" hidden>
+        This browser doesn't support creating passkeys. You can still manage existing passkeys here, or protect
+        your account with <a href="/account/security">two-step verification</a>.
+      </p>
+
+      <ul id="passkey-list" class="passkey-list" aria-busy="true" aria-labelledby="passkeys-title"></ul>
+      <p id="passkey-empty" class="empty" hidden>No passkeys found. Create one to sign in faster next time.</p>
+    </section>
+
+    <p id="status" class="status" role="status" aria-live="polite"></p>
+  </main>
+
+  <template id="passkey-row">
