+      <h2 id="rename-title">Rename passkey</h2>
+      <label>
+        <span>Passkey name</span>
+        <input name="name" type="text" required maxlength="64" autocomplete="off" autofocus>
+      </label>
+      <div class="dialog-actions">
+        <button type="submit" value="cancel" formnovalidate class="btn-secondary">Cancel</button>
+        <button type="submit" value="save" class="btn">Save</button>
+      </div>
+    </form>
+  </dialog>
+
+  <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
+    <form method="dialog">
+      <h2 id="delete-title">Delete passkey?</h2>
+      <p id="delete-desc">
+        You'll no longer be able to sign in with <strong id="delete-name"></strong>.
+        <span id="delete-last-warning" hidden>This is your only passkey — make sure you can still sign in another
+          way.</span>
+      </p>
+      <div class="dialog-actions">
+        <button value="cancel" class="btn-secondary" autofocus>Keep passkey</button>
+        <button value="delete" class="btn-danger">Delete</button>
+      </div>
+    </form>
+  </dialog>
+
+  <footer>
+    <div class="footer-links">
+      <a href="/about">Our Story</a> |
+      <a href="/careers">Join the Team</a> |
+      <a href="/contact">Contact Us</a> |
+      <a href="/privacy-policy">Privacy</a>
