+            throw new Error('Server could not verify the passkey.');
+          }
+          setStatus('Your passkey has been created. You can now use it to sign in.', 'success');
+        } catch (err) {
+          console.error('Passkey registration failed:', err && err.name, err && err.message);
+          setStatus(err && err.status ? 'Something went wrong on our side. Please try again.' : friendlyError(err), 'error');
+        } finally {
+          inFlight = false;
+          button.disabled = false;
+          button.removeAttribute('aria-busy');
+        }
+      }
+
+      button.addEventListener('click', registerPasskey);
+    })();
+  </script>
+
 </body>

 </html>

