+          <button type="button" class="acct-link acct-danger" data-action="remove">Remove</button>
+        </div>
+      </div>
+      <form class="acct-inline" data-form="rename" hidden novalidate>
+        <input name="name" type="text" maxlength="48" required aria-label="Passkey name">
+        <button type="submit" class="acct-btn acct-btn-small acct-btn-primary">Save</button>
+        <button type="button" class="acct-btn acct-btn-small" data-action="cancel">Cancel</button>
+      </form>
+      <div class="acct-inline" data-confirm="remove" hidden>
+        <span>Remove this passkey? You won’t be able to sign in with it anymore.</span>
+        <button type="button" class="acct-btn acct-btn-small acct-btn-danger" data-action="confirm-remove">Remove</button>
+        <button type="button" class="acct-btn acct-btn-small" data-action="cancel">Cancel</button>
+      </div>
+    </li>
+  </template>
+
 </body>

 </html>
