+import React from 'react';
+
+export const inputClass =
+  'w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500';
+
+export const primaryButtonClass =
+  'inline-flex items-center justify-center gap-2 py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-gray-900 disabled:opacity-60 disabled:cursor-not-allowed';
+
+export const secondaryButtonClass =
+  'inline-flex items-center justify-center gap-2 py-2 px-4 border border-gray-300 rounded-md text-sm font-medium text-gray-800 bg-white hover:bg-gray-50 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-gray-900 disabled:opacity-60 disabled:cursor-not-allowed';
+
+export const dangerButtonClass =
+  'inline-flex items-center justify-center gap-2 py-2 px-4 border border-transparent rounded-md text-sm font-medium text-white bg-red-700 hover:bg-red-800 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-red-700 disabled:opacity-60';
+
+export function Alert({ kind, children }: { kind: 'error' | 'success' | 'info'; children: React.ReactNode }) {
+  const styles = {
+    error: 'text-red-700 bg-red-100',
+    success: 'text-green-700 bg-green-100',
+    info: 'text-gray-700 bg-gray-100',
+  }[kind];
+  return (
+    <div className={`mb-4 p-3 text-sm rounded-lg ${styles}`} role={kind === 'error' ? 'alert' : 'status'}>
+      {children}
+    </div>
+  );
+}
+
+/** Generic passkey glyph (person + key). */
+export function PasskeyIcon({ className = 'w-5 h-5' }: { className?: string }) {
+  return (
+    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.8} aria-hidden="true">
+      <circle cx="9" cy="7" r="4" />
+      <path d="M2 21v-1a6 6 0 0 1 6-6h2" strokeLinecap="round" />
+      <circle cx="17" cy="14" r="2.5" />
+      <path d="M17 16.5V22m0-2h2m-2-1.5h1.5" strokeLinecap="round" />
+    </svg>
+  );
+}
+
+export const withBase = (path: string) => `${import.meta.env.BASE_URL.replace(/\/?$/, '/')}${path.replace(/^\//, '')}`;
+
+/** Only allow same-site relative redirects from ?next=. */
+export function getNextUrl(fallback = 'account') {
+  if (typeof window === 'undefined') return withBase(fallback);
+  const next = new URLSearchParams(window.location.search).get('next');
+  if (next && next.startsWith('/') && !next.startsWith('//')) return next;
+  return withBase(fallback);
+}
