+
+  const { displayName } = await readJson<{ displayName?: string }>(context.request);
+  const name = displayName?.trim();
+  if (!name) return error('Display name is required.');
+  if (name.length > 64) return error('Display name must be 64 characters or fewer.');
+
+  const updated = await updateUser(user.username, { displayName: name });
+  return json({ user: publicUser(updated!, getRelyingParty(context).rpID) });
+};
