+  const passkeys = await listPasskeys(user.id);
+  return json({
+    user: toPublicUser(user),
+    passkeys: passkeys.map(toPublicPasskey),
+    reauthExpiresAt: auth ? auth.authenticatedAt + REAUTH_WINDOW_MS : 0,
+  });
+};
