+# Security & privacy response headers.
+# Format: Netlify / Cloudflare Pages `_headers`. If you use another host or a
+# reverse proxy (nginx, Caddy, etc.), set the same headers there.
+# The CSP must match the <meta http-equiv="Content-Security-Policy"> fallback
+# in index.html. frame-ancestors and report-to only work as headers.
+
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'self'; manifest-src 'self'; form-action 'self'; base-uri 'none'; object-src 'none'; frame-ancestors 'none'; upgrade-insecure-requests
+  Strict-Transport-Security: max-age=63072000; includeSubDomains; preload
+  Referrer-Policy: strict-origin-when-cross-origin
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin
+  Cross-Origin-Resource-Policy: same-origin
+  Cross-Origin-Embedder-Policy: require-corp
+  Origin-Agent-Cluster: ?1
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), autoplay=(), battery=(), browsing-topics=(), camera=(), display-capture=(), document-domain=(), encrypted-media=(), fullscreen=(self), geolocation=(), gyroscope=(), hid=(), identity-credentials-get=(), idle-detection=(), interest-cohort=(), magnetometer=(), microphone=(), midi=(), payment=(), picture-in-picture=(), publickey-credentials-get=(self), screen-wake-lock=(), serial=(), usb=(), xr-spatial-tracking=()
+  X-Permitted-Cross-Domain-Policies: none
+  X-DNS-Prefetch-Control: off
+
+/index.html
+  Cache-Control: no-cache
+
+/
+  Cache-Control: no-cache
+
+/assets/*
+  Cache-Control: public, max-age=86400
+
+# Signed-in pages carry personal data: never store them in shared or browser caches.
+/account
+  Cache-Control: no-store
+/account/*
+  Cache-Control: no-store
+/rewards
+  Cache-Control: no-store
+/order-online
+  Cache-Control: no-store
+
+# Logout wipes cookies, storage, and cache for this origin.
+/logout
+  Cache-Control: no-store
+  Clear-Site-Data: "cache", "cookies", "storage"
+
+/.well-known/gpc.json
+  Content-Type: application/json
+  Access-Control-Allow-Origin: *
+  Cross-Origin-Resource-Policy: cross-origin
