+  border: 0;
+  margin: 0 10px;
+  color: var(--text);
+  font: inherit;
+  font-size: 0.85rem;
+  cursor: pointer;
+  text-decoration: underline;
+}
+
+.privacy-note {
+  font-size: 0.8rem;
+  margin-bottom: 10px;
+}
+
+/* Privacy choices dialog */
+.privacy-dialog {
+  max-width: 480px;
+  width: calc(100% - 40px);
+  margin: auto;
+  border: 0;
+  border-radius: 8px;
+  padding: 24px;
+  color: var(--text);
+  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
+}
+
+.privacy-dialog::backdrop {
+  background: rgba(0, 0, 0, 0.5);
+}
+
+.privacy-dialog h2 {
+  margin-bottom: 10px;
+  color: var(--primary);
+}
+
+.privacy-dialog fieldset {
+  border: 1px solid var(--secondary);
+  border-radius: 6px;
+  padding: 12px;
+  margin: 15px 0;
+}
+
+.privacy-dialog label {
+  display: flex;
+  gap: 10px;
+  align-items: flex-start;
+  margin: 8px 0;
+}
+
+.privacy-dialog small {
+  display: block;
+  color: #6d4c41;
+}
+
+.privacy-signal {
+  background: #fff3e0;
+  border-left: 4px solid var(--accent);
+  padding: 8px 12px;
+  font-size: 0.85rem;
+}
+
+.dialog-actions {
+  display: flex;
+  justify-content: flex-end;
+  gap: 10px;
+}
+
+.dialog-actions .btn {
+  border: 0;
+  font: inherit;
+  cursor: pointer;
+  margin-top: 0;
+}
+
+.btn-secondary {
+  background: var(--secondary);
+  color: var(--text);
+}
+
+.btn-secondary:hover {
+  background: #bcaaa4;
+}
+
+[hidden] {
+  display: none !important;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  * {
+    transition: none !important;
+  }
+}
