@@ -0,0 +1,69 @@
+// Newsletter signup: progressively enhances the <form>, which still works without JS.
+const form = document.getElementById('newsletter-form');
+
+if (form) {
+  const email = form.elements.namedItem('email');
+  const button = form.querySelector('button[type="submit"]');
+  const status = document.getElementById('newsletter-status');
+
+  const setStatus = (message, state) => {
+    status.textContent = message;
+    if (state) status.dataset.state = state;
+    else delete status.dataset.state;
+  };
+
+  email.addEventListener('input', () => {
+    email.removeAttribute('aria-invalid');
+    if (status.dataset.state === 'error') setStatus('', null);
+  });
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+
+    if (!email.checkValidity()) {
+      email.setAttribute('aria-invalid', 'true');
+      setStatus('Please enter a valid email address, like name@example.com.', 'error');
+      email.focus();
+      return;
+    }
+
+    button.disabled = true;
+    setStatus('Signing you up…', null);
+
+    try {
+      const response = await fetch(form.action, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+        body: JSON.stringify({ email: email.value.trim() }),
+        credentials: 'same-origin',
+      });
+
+      let payload = null;
+      try {
+        payload = await response.json();
+      } catch {
+        // Non-JSON response; fall through to the generic message.
+      }
+
+      if (!response.ok) {
+        setStatus(
+          payload?.error || 'Sorry, we couldn’t sign you up right now. Please try again in a moment.',
+          'error',
+        );
+        return;
+      }
+
+      form.reset();
+      setStatus(payload?.message || 'Thanks! You’re on the list.', 'success');
+    } catch {
+      // Network failure, offline, or the request was blocked by the page's
+      // connection policy (Connection-Allowlist / CSP reject fetch with a TypeError).
+      setStatus(
+        'We couldn’t reach our server, so your signup didn’t go through. Check your connection and try again.',
+        'error',
+      );
+    } finally {
+      button.disabled = false;
+    }
+  });
+}
