--- /dev/null
+++ b/public/app.js
@@ -0,0 +1,80 @@
+'use strict';
+
+(function () {
+  var form = document.getElementById('newsletter-form');
+  if (!form) return;
+
+  var emailInput = document.getElementById('newsletter-email');
+  var button = form.querySelector('button[type="submit"]');
+  var status = document.getElementById('newsletter-status');
+  var REQUEST_TIMEOUT_MS = 10000;
+  var EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+  var MESSAGES = {
+    invalid: 'Please enter a valid email address.',
+    rateLimited: 'Too many attempts. Please wait a minute and try again.',
+    network: "We couldn't reach our server. Please check your connection and try again.",
+    timeout: 'The request took too long. Please try again in a moment.',
+    server: 'Something went wrong on our end. Please try again later.'
+  };
+
+  function showStatus(message, kind) {
+    status.textContent = message;
+    status.className = 'newsletter-status ' + (kind === 'success' ? 'is-success' : 'is-error');
+    status.hidden = false;
+  }
+
+  function setBusy(busy) {
+    button.disabled = busy;
+    button.textContent = busy ? 'Subscribing…' : 'Subscribe';
+    form.setAttribute('aria-busy', busy ? 'true' : 'false');
+  }
+
+  form.addEventListener('submit', function (event) {
+    event.preventDefault();
+
+    var email = emailInput.value.trim();
+    if (!EMAIL_PATTERN.test(email) || email.length > 254) {
+      showStatus(MESSAGES.invalid, 'error');
+      emailInput.focus();
+      return;
+    }
+
+    var controller = typeof AbortController === 'function' ? new AbortController() : null;
+    var timer = controller ? setTimeout(function () { controller.abort(); }, REQUEST_TIMEOUT_MS) : null;
+
+    setBusy(true);
+
+    // Same-origin relative URL only; the CSP connect-src 'self' blocks anything else.
+    fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
+      body: JSON.stringify({ email: email }),
+      credentials: 'same-origin',
+      signal: controller ? controller.signal : undefined
+    })
+      .then(function (response) {
+        return response.json().catch(function () { return {}; }).then(function (data) {
+          if (response.ok) {
+            showStatus(data.message || "Thanks for subscribing! Watch your inbox for our next brew.", 'success');
+            form.reset();
+          } else if (response.status === 400) {
+            showStatus(MESSAGES.invalid, 'error');
+          } else if (response.status === 429) {
+            showStatus(MESSAGES.rateLimited, 'error');
+          } else {
+            showStatus(MESSAGES.server, 'error');
+          }
+        });
+      })
+      .catch(function (err) {
+        // Network failures, offline, and requests blocked by the Content Security Policy
+        // all reject here.
+        showStatus(err && err.name === 'AbortError' ? MESSAGES.timeout : MESSAGES.network, 'error');
+      })
+      .then(function () {
+        if (timer) clearTimeout(timer);
+        setBusy(false);
+      });
+  });
+})();
