+import type { APIRoute } from 'astro';
+import { normalizePhone, verifyCode } from '../../../lib/phoneVerification';
+
+const json = (body: unknown, status = 200) =>
+  new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+
+export const POST: APIRoute = async ({ request }) => {
+  let body: { phone?: unknown; code?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const phone = normalizePhone(body.phone);
+  if (!phone) return json({ error: 'Invalid phone number.' }, 400);
+
+  const result = verifyCode(phone, body.code);
+  if (!result.ok) return json({ error: result.error }, result.status);
+
+  return json({ phone, verificationToken: result.verificationToken });
+};

