+  <script type="module">
+    const menu = document.getElementById('coffee-menu');
+    const tablist = menu.querySelector('[role="tablist"]');
+    const tabs = [...tablist.querySelectorAll('[role="tab"]')];
+    const panels = tabs.map(tab => document.getElementById(tab.id.replace(/^tab-/, 'panel-')));
+
+    function select(tab) {
+      if (tab.getAttribute('aria-selected') !== 'true') {
+        tabs.forEach((t, i) => {
+          const isSelected = t === tab;
+          t.setAttribute('aria-selected', String(isSelected));
+          t.toggleAttribute('focusgroupstart', isSelected);
+          if (isSelected) {
+            panels[i].removeAttribute('hidden');
+          } else {
+            // Falls back to plain `hidden` where until-found isn't supported
+            panels[i].hidden = 'until-found';
+          }
+        });
+      }
+      // Reveal the selected tab (and a peek of its neighbour) inside the tab bar only, not the page
+      tab.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' });
+    }
+
+    // Selection follows focus (arrow keys via focusgroup); click covers Safari, which doesn't focus buttons on click
+    tablist.addEventListener('focusin', e => {
+      const tab = e.target.closest('[role="tab"]');
+      if (tab) select(tab);
+    });
+    tablist.addEventListener('click', e => {
+      const tab = e.target.closest('[role="tab"]');
+      if (tab) select(tab);
+    });
+
+    // Find-in-page revealed a hidden panel: sync the tab selection with it
+    panels.forEach((panel, i) => {
+      panel.addEventListener('beforematch', () => select(tabs[i]));
+    });
+
+    // Edge-fade fallback for browsers without scroll-driven animations
+    if (!CSS.supports('animation-timeline', 'scroll()')) {
+      const [first, last] = [tabs[0], tabs.at(-1)];
+      // rootMargin absorbs sub-pixel widths that would leave an edge tab a hair short of fully visible
+      const observer = new IntersectionObserver(entries => {
+        for (const { target, intersectionRatio } of entries) {
+          tablist.classList.toggle(target === first ? 'more-start' : 'more-end', intersectionRatio < 1);
+        }
+      }, { root: tablist, threshold: 1, rootMargin: '1px' });
+      observer.observe(first);
+      observer.observe(last);
+    }
+
+    // Arrow-key roving focus: native focusgroup, else the polyfill, else a minimal handler
+    if (!Object.hasOwn(HTMLElement.prototype, 'focusGroup')) {
+      try {
+        const { polyfill } = await import('https://esm.sh/@microsoft/focusgroup-polyfill');
+        polyfill();
+      } catch {
+        tabs.forEach(t => { t.tabIndex = t.getAttribute('aria-selected') === 'true' ? 0 : -1; });
+        tablist.addEventListener('focusin', () => {
+          tabs.forEach(t => { t.tabIndex = t.getAttribute('aria-selected') === 'true' ? 0 : -1; });
