+}
+/*
+ * Semantic surface context
+ * ------------------------
+ * Sections declare *what they are* via `data-surface="featured"`; they never
+ * name the components that react. Teaser components opt in to react to the
+ * inherited `--surface` flag through container style queries.
+ */
+@layer components {
+  [data-surface="featured"] {
+    --surface: featured;
+  }
+
+  [data-surface="default"] {
+    --surface: default;
+  }
+
+  /* Default (subtle) presentation — works everywhere */
+  .teaser-badge {
+    display: none;
+    align-items: center;
+    gap: 0.25rem;
+    width: fit-content;
+    margin-block-end: 0.5rem;
+    padding: 0.125rem 0.5rem;
+    border-radius: 9999px;
+    background: var(--color-amber-400);
+    color: var(--color-gray-900);
+    font-size: 0.6875rem;
+    font-weight: 700;
+    letter-spacing: 0.08em;
+    text-transform: uppercase;
+  }
+
+  .teaser-action {
+    display: inline-flex;
+    align-items: center;
+    gap: 0.25rem;
+    padding: 0.25rem 0.75rem;
+    border: 1px solid currentColor;
+    border-radius: 0.375rem;
+    background: transparent;
+    color: var(--color-gray-700);
+    font-size: 0.875rem;
+    font-weight: 600;
+    transition: background-color 150ms, color 150ms, border-color 150ms;
+  }
+
+  .teaser-action:hover {
+    background: var(--color-gray-100);
+  }
+
+  .teaser-action:focus-visible {
+    outline: 2px solid var(--color-amber-400);
+    outline-offset: 2px;
+  }
+
+  /* Selector-based fallback for browsers without container style queries.
+     :where() keeps specificity equal so the style query below wins. */
+  :where([data-surface="featured"]) .teaser-badge {
+    display: inline-flex;
+  }
+
+  :where([data-surface="featured"]) .teaser-action {
+    border-color: var(--color-amber-400);
+    background: var(--color-amber-400);
+    color: var(--color-gray-900);
+  }
+
+  :where([data-surface="featured"]) .teaser-action:hover {
+    border-color: var(--color-amber-500);
+    background: var(--color-amber-500);
+  }
+
+  /* Progressive enhancement: react to the inherited semantic flag */
+  @container style(--surface: featured) {
+    .teaser-badge {
+      display: inline-flex;
+    }
+
+    .teaser-action {
+      border-color: var(--color-amber-400);
+      background: var(--color-amber-400);
+      color: var(--color-gray-900);
+    }
+
+    .teaser-action:hover {
+      border-color: var(--color-amber-500);
+      background: var(--color-amber-500);
+    }
+  }
+
+  @container style(--surface: default) {
+    .teaser-badge {
+      display: none;
+    }
+
+    .teaser-action {
+      border-color: currentColor;
+      background: transparent;
+      color: var(--color-gray-700);
+    }
+
+    .teaser-action:hover {
+      background: var(--color-gray-100);
+    }
+  }
+}

