+/**
+ * Shared constructable stylesheets adopted by every Daily Grind component.
+ * Theme tokens are CSS custom properties defined on :root in the page, which
+ * inherit through shadow boundaries, so components stay themeable while their
+ * internal styles remain encapsulated.
+ */
+
+const sheet = (css) => {
+  const s = new CSSStyleSheet();
+  s.replaceSync(css);
+  return s;
+};
+
+export const baseStyles = sheet(`
+  :host {
+    box-sizing: border-box;
+    font-family: inherit;
+    color: var(--text, #3e2723);
+  }
+  *, *::before, *::after { box-sizing: inherit; }
+
+  .visually-hidden {
+    position: absolute !important;
+    width: 1px; height: 1px;
+    padding: 0; margin: -1px;
+    overflow: hidden;
+    clip: rect(0 0 0 0);
+    white-space: nowrap;
+    border: 0;
+  }
+
+  :focus-visible {
+    outline: 3px solid var(--focus-ring, var(--accent, #ffab40));
+    outline-offset: 2px;
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    *, *::before, *::after {
+      transition-duration: 0.01ms !important;
+      animation-duration: 0.01ms !important;
+    }
+  }
+`);
+
+/** Button look shared by shadow-DOM buttons/links (.btn) and slotted CTAs. */
+export const buttonCss = `
+  display: inline-block;
+  background: var(--primary, #4e342e);
+  color: #fff;
+  padding: 10px 20px;
+  text-decoration: none;
+  border: 0;
+  border-radius: 5px;
+  font: inherit;
+  cursor: pointer;
+  transition: background 0.3s;
+`;
+
+export const buttonStyles = sheet(`
+  .btn { ${buttonCss} }
+  .btn:hover { background: var(--primary-dark, #3e2723); }
+`);
